B.aNb=new A.lb("condolence","\ud83d\udd4a\ufe0f",B.GV,B.aKF)
B.af9=s(["Selam {name}! Unutmu\u015fsundur diye hat\u0131rlatay\u0131m: {what} \xf6demesi h\xe2l\xe2 duruyor. Uygun oldu\u011funda g\xf6nderirsen sevinirim \ud83d\ude0a","{name}, rahats\u0131z etmek istemem ama {what} konusunu bir hat\u0131rlatay\u0131m dedim. M\xfcsait olunca bakabilir misin?"],t.s)
B.aq4=s(["Say\u0131n {name}, {what} tutar\u0131ndaki \xf6demenin hen\xfcz taraf\u0131m\u0131za ula\u015fmad\u0131\u011f\u0131n\u0131 hat\u0131rlatmak isterim. En k\u0131sa s\xfcrede \xf6demenizi rica ederim.","{name}, {what} ile ilgili \xf6demenin vadesi ge\xe7mi\u015ftir. Bilgilerinize sunar, \xf6demenizi rica ederim."],t.s)
